(window.webpackJsonp=window.webpackJsonp||[]).push([[129],{456:function(t,e,a){"use strict";a.r(e);var s=a(33),n=Object(s.a)({},function(){var t=this.$createElement,e=this._self._c||t;return e("ContentSlotsDistributor",{attrs:{"slot-key":this.$parent.slotKey}},[e("h1",{attrs:{id:"olagenheter-vid-mma-svetsning"}},[e("a",{staticClass:"header-anchor",attrs:{href:"#olagenheter-vid-mma-svetsning","aria-hidden":"true"}},[this._v("#")]),this._v(" Olägenheter vid MMA-svetsning")]),this._v(" "),e("p",[this._v("De olägenheter som kan uppstå vid Manuell Metallbågsvetsning är i första hand det intensiva skenet från ljusbågen och den relativt kraftiga rökutvecklingen, men också heta stänk från smältbadet och ett magnetisk kraftfält runt svetskablarna. Det intensiva skenet i ljusbågen innehåller både ultraviolett och infraröd strålning. Av den anledningen skall svetsaren använda färgade skyddsglas som finns i olika täthet (opacitet). Ett oskyddat öga riskerar att bli utsatt för svetsblänk, som är en brännskada på hornhinnan och mycket smärtsam. För att skydda sig mot svetsröken behövs ordentliga utsug som tar bort röken så nära ljusbågen som möjligt (punktutsug). Tänk på att rök från t.ex. rostfria och manganlegerade elektroder kan vara mycket skadlig. För att undvika heta stänk skall svetsaren ha heltäckande skyddskläder, t.ex. en flamsäker overall, svetshandskar, damasker, förkläde och vid grövre svetsning också halsduk och huvudbonad. Det magnetiska kraftfält som uppstår runt en svetsledare kan vara skadligt. Ha därför aldrig svetskablarna runt halsen. Vid svetsning med t.ex. MMA på höga parametrar kan det en fördel om svetskablarna tejpas samman.")])])},[],!1,null,null,null);e.default=n.exports}}]);